insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8ce90839-46ac-4c09-88d3-7e5231bbade8', 'fr', 'Tu remarques un joli tatouage sur son bras. Quelle accroche montre de la curiosité ?', '["« Il a une histoire, ce tatouage ? Il est vraiment cool. »", "« Ce tatouage te rend sexy. »", "« Tu as un style cool. »", "« Tu en as d’autres, des tatouages ? »"]'::jsonb, 'Être curieux de ce qu’elle vit invite un vrai lien, sans arrière-pensée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90a2ae5f-3f19-4289-983b-90a3660b1de9', 'fr', 'Que se passe-t-il quand on ignore des signaux polis ou froids ?', '["L’attirance se construit lentement", "Le confort diminue", "L’échange s’approfondit", "L’intérêt se précise"]'::jsonb, 'Ignorer les signaux augmente la tension et le malaise ; pars dès que tu les remarques.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('92fc8147-e976-4d33-824a-5ea94444d15c', 'fr', 'Pourquoi une supposition fausse marche-t-elle souvent quand même ?', '["La correction crée quand même de l’implication et de l’élan", "Se tromper réduit la pression", "Les femmes aiment corriger les hommes"]'::jsonb, 'Que tu aies raison ou tort, elle doit s’impliquer pour répondre. L’implication, c’est le but.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94a93921-8975-4a5a-ac8a-918d2cfeb071', 'fr', 'Pourquoi aborder avec curiosité ?', '["Ça cache l’attirance", "Ça évite le rejet", "Ça marche comme une astuce psychologique", "Ça réduit la pression et lui donne le sentiment d’être intéressante"]'::jsonb, 'On s’ouvre quand on se sent vu, pas évalué ou poursuivi.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95d93e33-2d1c-431f-a2f0-0ed76d7c559c', 'fr', 'À la salle de sport, tu engages la conversation. Elle répond chaleureusement, puis remet ses écouteurs.', '["Ouverture : elle a répondu complètement, elle est impliquée", "Politesse : elle a répondu par courtoisie, mais ne veut pas continuer", "Froideur : un comportement impoli qui veut dire que tu dois partir immédiatement"]'::jsonb, 'Elle t’a répondu, puis a posé une limite ; retire-toi sans prolonger.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('96cd2c07-1109-4ded-b869-cec66cf863b9', 'fr', 'Dans un bar, tu l’abordes directement. Son amie arrive, et elle se tourne légèrement vers elle.', '["Continuer à parler sans t’adapter", "Rivaliser pour son attention", "Lui faire remarquer qu’elle s’est tournée", "Saluer son amie ou partir proprement"]'::jsonb, 'S’ajuster, c’est s’adapter quand la dynamique change.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('97f948e5-43c9-49fb-91ea-249d0532afa8', 'fr', 'À une soirée, elle se tient près des boissons. Quelle accroche directe convient le mieux ?', '["« Je t’ai vue de l’autre bout de la pièce, il fallait que je vienne te rencontrer. »", "« Elle est forte, la musique, non ? »", "« Tu sais où sont les toilettes ? »", "« Tu viens souvent ici ? »"]'::jsonb, 'Exprimer clairement ton intérêt colle naturellement au cadre d’une soirée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('99e493d5-07b4-4d19-ad59-483e3579a8d1', 'fr', 'Qu’est-ce qui rend efficace une accroche qui demande son avis ?', '["Elle explique pourquoi tu lui poses la question à elle, pas à n’importe qui", "Elle présente son point de vue comme précieux et important", "Elle crée un débat qui fait naître tension et attirance"]'::jsonb, 'Les gens s’illuminent quand leur point de vue compte. Se sentir valorisé crée de l’implication.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9a58e14a-b997-4eae-a453-494d620dffc6', 'fr', 'Dans un bar, tu dis : « Toi, tu es clairement l’amie raisonnable qui ramène tout le monde. » Qu’est-ce qui marche ?', '["La supposition précise l’a obligée à répondre et à s’impliquer tout de suite", "Elle est curieuse de savoir comment tu en es arrivé à cette conclusion", "Les deux réponses ci-dessus"]'::jsonb, 'Une supposition précise appelle une réponse et crée une implication immédiate.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9c7e0b10-8bac-4319-8672-b7ce62646374', 'fr', 'Tu es à côté d’elle dans un bar bondé. Quelles accroches indirectes peux-tu utiliser ?', '["Lui demander si le bar est toujours aussi plein", "Lui demander ce qu’elle commande", "Lui dire qu’elle est attirante", "Lui demander son Instagram"]'::jsonb, 'Une remarque sur le lieu donne l’impression de rejoindre le moment, pas de l’interrompre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9cf11184-5b92-4e5e-ac1b-12519aa0d194', 'fr', 'Elle sourit poliment, mais retourne à son téléphone après une brève réponse. Qu’est-ce que ça indique ?', '["Une tolérance polie, pas un vrai intérêt", "Une forte ouverture cachée par la timidité", "Un rejet froid qui demande d’insister", "Une invitation claire à continuer"]'::jsonb, 'Un sourire poli suivi d’un décrochage montre de la neutralité, pas de l’investissement.')
