insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a281e41d-8c59-42aa-8e23-5071d84c9c8c', 'fr', 'Pourquoi « Mon pote et moi, on débat d’un truc… » marche-t-il comme entrée en matière ?', '["Ça la rend curieuse de connaître le débat", "Ça fait de son avis l’arbitre, ce qui la valorise", "Ça montre ta preuve sociale, puisque tu as des amis"]'::jsonb, 'Un débat ou un dilemme sollicite son avis, ce qui la valorise et l’implique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a445b565-f83a-4031-9b70-7201a9b11bc3', 'fr', 'Quel signal envoies-tu quand tu orientes la conversation ?', '["De l’assurance", "Que tu sais mener", "Une direction", "Toutes les réponses ci-dessus"]'::jsonb, 'Choisir le sujet montre ton assurance et que tu sais mener ; donne une direction au lieu d’attendre.')
