insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a51060bf-7646-4967-a8bf-730e53f6714d', 'fr', 'Pourquoi commencer par « Salut, j’ai une question pour toi » éveille-t-il efficacement la curiosité ?', '["Ça crée de l’incertitude : elle veut savoir quelle est la question", "Ça montre de l’assurance en interrompant ce qu’elle fait", "Ça te présente comme quelqu’un qui a besoin de quelque chose, ce qui lui fait baisser la garde"]'::jsonb, 'Quand une information est incomplète, le cerveau cherche à la compléter ; sers-t’en pour capter son attention.')
