insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a95654fc-2f4a-4b06-a6d7-ce66be1aaac1', 'fr', 'Vous flânez tous les deux dans une librairie. Quelles accroches indirectes peux-tu utiliser ?', '["Lui demander si elle connaît ce livre", "Lui dire qu’elle a attiré ton regard", "Lui demander son numéro", "Faire une remarque sur le talent de cet auteur"]'::jsonb, 'Les accroches d’observation se fondent dans le moment.')
