insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ab9eedd4-bf67-486a-8b3c-938ef10f4137', 'fr', 'Pourquoi est-il logique d’aborder plutôt que de rester immobile ?', '["L’inaction garantit l’échec ; l’action crée une possibilité", "Aborder crée l’attirance plus vite", "L’action garantit la confiance"]'::jsonb, 'Quand tu ne fais rien, rien ne peut arriver. Quand tu agis, quelque chose peut arriver.')
