insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ada0ea94-3879-4702-b335-f62a57dd6045', 'fr', 'Pourquoi prend-on si facilement une réponse polie pour de l’intérêt ?', '["Elle s’accompagne d’un regard et d’amabilité", "Les femmes évitent les refus brutaux", "Les hommes projettent leur désir sur des signaux neutres", "Toutes les réponses ci-dessus"]'::jsonb, 'Les signaux polis sont volontairement doux ; fie-toi plutôt à une attention qui dure et aux questions qu’elle te pose.')
