insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b22764cf-ce02-4bf8-8eb7-5fb7926333ed', 'fr', 'Tu remarques que son livre a une couverture intéressante. Que pourrais-tu dire en premier pour éveiller sa curiosité ?', '["« C’est quoi, ce livre ? »", "« Tu lis beaucoup ? »", "« Il a l’air intéressant. »", "« Il faut que je te demande un truc sur le livre que tu tiens. »"]'::jsonb, 'La mise en place crée de la curiosité avant de révéler la question.')
