insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b2eb7c50-c714-4003-a310-0084c29f7fcc', 'fr', 'Qu’est-ce qui permet aux accroches indirectes de réduire la pression ?', '["Ce sont des phrases toutes prêtes qui marchent dans plein de situations", "Elle n’a pas à décider tout de suite si tu lui plais", "Elles cachent ton intention derrière une conversation plausible et détendue"]'::jsonb, 'Les accroches indirectes ressemblent à la suite naturelle du moment que vous vivez déjà.')
