insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b32bbd22-abe6-4fd4-9f13-deaaad94298d', 'fr', 'Tu vois qu’elle a une coque de téléphone à motif de plantes. Quelle accroche montre de la curiosité ?', '["« Elle est mignonne, ta coque. »", "« Tu jardines ? »", "« Il est joli, ton téléphone. »", "« Tu es fan de plantes ? Il y en a des sympas sur ta coque. »"]'::jsonb, 'Être curieux de ce qu’elle vit invite un vrai lien, sans arrière-pensée.')
